#include <bits/stdc++.h>
using namespace std;

using LL = long long;
using Pair = pair<LL, LL>;

const int MAX_LIMIT = 100002;
const LL MAX_INF = 1000000007;
const long double TOLERANCE = 1e-15;

LL x_input, y_input, max_b;
long double min_difference = MAX_INF;
Pair result;

void try_update(LL b_value, LL a_value) {
    long double diff = fabs((long double)a_value / b_value - (long double)x_input / y_input);
    if (diff + TOLERANCE < min_difference) {
        min_difference = diff;
        result = {b_value, a_value};
    }
}

int main() {
    cin >> x_input >> y_input >> max_b;
    for (LL b = 1; b <= max_b; ++b) {
        LL a_floor = (x_input * b) / y_input;
        LL a_ceil = a_floor + 1;
        try_update(b, a_floor);
        try_update(b, a_ceil);
    }
    cout << result.second << '/' << result.first;
    return 0;
}
